/// <summary>
/// Extension class of form data source SalesTable in form SalesTableListPage
/// </summary>
[ExtensionOf(formDataSourceStr(SalesTableListPage, SalesTable))]
internal final class METSalesTableListPageSalesTableDS_Extension
{
}

Method.Source:
    /// <summary>
    /// active method on ST datasource
    /// </summary>
    /// <returns>
    /// int
    /// </returns>
    int active()
    {
        int ret = next active();

        this.METEnableCustomBtn();
        return ret;
    }

/// <summary>
/// enable/disable custom buttons
/// </summary>
private void METEnableCustomBtn()
{
    SalesTable salesTable = this.cursor() as SalesTable;
    this.formRun().control(this.formRun().controlId(formControlStr(SalesTableListPage, METTMSEngineSalesOrderCancellation))).enabled(salesTable.SalesStatus == SalesStatus::Canceled);
    this.formRun().control(this.formRun().controlId(formControlStr(SalesTableListPage, METTMSEngineSalesOrderCreation))).enabled(salesTable.METAllowTMSCreation());
    this.formRun().control(this.formRun().controlId(formControlStr(SalesTableListPage, METTMSEngineSalesOrderPickingList))).enabled(salesTable.METAllowTMSExtraction());
}
